import { toAISdkMessages } from "@mastra/ai-sdk/ui";
import { isToolUIPart, readUIMessageStream, type UIMessage } from "ai";
import { MockLanguageModelV3 } from "ai/test";
import { z } from "zod";
import { githubToolNeedsApproval, isGithubReadTool } from "./src/mastra/tools/github";
import { approvalResumeMessage, pendingApprovalIds } from "./src/chat-approvals";

// ---- 1. Predicate ----
const reads = ["get_me", "get_file_contents", "list_issues", "list_pull_requests", "search_code", "search_issues", "issue_read", "pull_request_read", "actions_get", "actions_list", "get_job_logs", "list_commits"];
const writes = ["create_issue", "issue_write", "add_issue_comment", "create_pull_request", "merge_pull_request", "update_pull_request", "create_or_update_file", "push_files", "delete_file", "create_branch", "pull_request_review_write", "actions_run_trigger", "fork_repository", "sub_issue_write", "run_secret_scanning", "assign_copilot_to_issue", "totally_unknown_tool", "", "GET_ME", "issue_readx"];
for (const t of reads) assert.equal(githubToolNeedsApproval({ toolName: t }), false, `read ${t}`);
for (const t of reads) assert.equal(githubToolNeedsApproval({ toolName: t, annotations: { readOnlyHint: true } }), false, `read+hint ${t}`);
for (const t of writes) assert.equal(githubToolNeedsApproval({ toolName: t }), true, `write ${t}`);
for (const t of writes) assert.equal(githubToolNeedsApproval({ toolName: t, annotations: { readOnlyHint: true } }), true, `write even if hinted read-only ${t}`);
assert.equal(githubToolNeedsApproval({ toolName: "list_issues", annotations: { readOnlyHint: false } }), true, "read name, non-read-only hint");
assert.equal(isGithubReadTool("create_issue"), false);
console.log(`predicate: ${reads.length} read tools pass, ${writes.length} mutating/unknown tools need approval`);

// ---- 2. Round trip through handleChatStream v7 with a mock model ----
const executed: string[] = [];
function mcpLikeTool(name: string) {
  const tool = createTool({
    id: `github_${name}`,
    description: name,
    inputSchema: z.object({ title: z.string().optional() }),
    requireApproval: true,
    execute: async (input) => {
      executed.push(name);
      return { ok: true, name, input };
    },
  });
  // Same wiring @mastra/mcp uses for a requireToolApproval function.
  (tool as unknown as { needsApprovalFn: unknown }).needsApprovalFn = (args: Record<string, unknown>) =>
    githubToolNeedsApproval({ toolName: name, annotations: undefined, ...{ args } });
  return tool;
}

const usage = { inputTokens: { total: 1, noCache: 1, cacheRead: 0, cacheWrite: 0 }, outputTokens: { total: 1, text: 1, reasoning: 0 } };
const scripted = [
  [{ type: "tool-call", toolCallId: "call-read", toolName: "github_list_issues", input: "{}" }],
  [{ type: "tool-call", toolCallId: "call-write", toolName: "github_create_issue", input: JSON.stringify({ title: "Hello" }) }],
  [{ type: "text-start", id: "t" }, { type: "text-delta", id: "t", delta: "Done." }, { type: "text-end", id: "t" }],
];
let call = 0;
const model = new MockLanguageModelV3({
  doStream: async () => {
    const parts = scripted[Math.min(call++, scripted.length - 1)];
    const finishReason = { unified: parts[0].type === "tool-call" ? "tool-calls" : "stop", raw: undefined };
