const agent = new Agent({
  id: "github",
  name: "GitHub Agent",
  instructions: "test",
  model,
  memory: new Memory({ options: { lastMessages: 20, semanticRecall: false, workingMemory: { enabled: false }, generateTitle: false } }),
  tools: { github_list_issues: mcpLikeTool("list_issues"), github_create_issue: mcpLikeTool("create_issue") },
  defaultOptions: { maxSteps: 6 },
});
const mastra = new Mastra({ storage: new LibSQLStore({ id: "t", url: `file:${join(dir, "t.db")}` }), agents: { agent }, logger: false });
const memoryIds = { thread: "u1:github", resource: "u1" };

async function drain(stream: ReadableStream<unknown>, start?: UIMessage) {
  const chunks: { type: string }[] = [];
  const [a, b] = (stream as ReadableStream<{ type: string }>).tee();
  const collect = (async () => { for await (const c of a as unknown as AsyncIterable<{ type: string }>) chunks.push(c); })();
  let last: UIMessage | undefined;
  for await (const m of readUIMessageStream({ stream: b as never, message: start })) last = m as UIMessage;
  await collect;
  return { chunks, message: last! };
