const s1 = await handleChatStream({
  mastra, agentId: "github", version: "v7",
  params: { messages: [{ id: "u1:m1", role: "user", parts: [{ type: "text", text: "open an issue" }] }], memory: memoryIds },
});
const r1 = await drain(s1 as never);
assert.ok(r1.chunks.some((c) => c.type === "tool-approval-request"), "stream carries tool-approval-request");
assert.deepEqual(executed, ["list_issues"], "read tool ran without approval; write tool did not run");
const requested = r1.message.parts.find((p) => isToolUIPart(p) && p.state === "approval-requested");
assert.ok(requested && isToolUIPart(requested) && requested.state === "approval-requested");
const approvalId = requested.approval.id;
console.log("1st stream: read tool executed, write suspended; approval id", approvalId);

// Persisted pending approval in the caller's own thread.
const mem = await agent.getMemory();
const stored = (await mem!.recall({ threadId: memoryIds.thread, resourceId: memoryIds.resource, perPage: false })).messages;
const pending = pendingApprovalIds(stored);
assert.ok(pending.has(approvalId), "pending approval recorded in thread metadata");
const history = toAISdkMessages(stored, { version: "v7" }) as UIMessage[];
assert.ok(history.some((m) => m.parts.some((p) => isToolUIPart(p) && p.state === "approval-requested" && p.approval.id === approvalId)), "history reload rehydrates approval-requested");
console.log("memory: pending approval stored and rehydrated by toAISdkMessages v7");

// Client response, as addToolApprovalResponse would produce it.
const responded: UIMessage = {
  ...r1.message,
  parts: r1.message.parts.map((p) => (p === requested ? { ...p, state: "approval-responded", approval: { id: approvalId, approved: true, reason: "x" } } : p)) as UIMessage["parts"],
};
assert.equal(approvalResumeMessage(responded, new Set()), undefined, "unknown/foreign approval rejected");
const forged = { ...responded, parts: responded.parts.map((p) => (isToolUIPart(p) && p.state === "approval-responded" ? { ...p, approval: { id: "other-run::call-write", approved: true } } : p)) } as UIMessage;
assert.equal(approvalResumeMessage(forged, pending), undefined, "forged approval id rejected");
const resume = approvalResumeMessage(responded, pending);
assert.ok(resume && resume.parts.length === 1);

const s2 = await handleChatStream({ mastra, agentId: "github", version: "v7", params: { messages: [resume], memory: memoryIds } });
const r2 = await drain(s2 as never, r1.message);
assert.deepEqual(executed, ["list_issues", "create_issue"], "write tool ran after approval");
assert.ok(r2.message.parts.some((p) => p.type === "text" && p.text.includes("Done.")), "reply continued after approval");
assert.equal(r2.message.id, r1.message.id, "resumed stream continues the same assistant message");
const after = pendingApprovalIds((await mem!.recall({ threadId: memoryIds.thread, resourceId: memoryIds.resource, perPage: false })).messages);
assert.equal(after.has(approvalId), false, "pending approval cleared after resume");
console.log("2nd stream: approval resumed the run, write tool executed, reply continued, pending cleared");

// ---- 3. Deny path ----
call = 1; // next model call: write tool again
executed.length = 0;
const s3 = await handleChatStream({ mastra, agentId: "github", version: "v7", params: { messages: [{ id: "u1:m2", role: "user", parts: [{ type: "text", text: "again" }] }], memory: memoryIds } });
const r3 = await drain(s3 as never);
const req3 = r3.message.parts.find((p) => isToolUIPart(p) && p.state === "approval-requested");
assert.ok(req3 && isToolUIPart(req3) && req3.state === "approval-requested");
const pending3 = pendingApprovalIds((await mem!.recall({ threadId: memoryIds.thread, resourceId: memoryIds.resource, perPage: false })).messages);
const denied = approvalResumeMessage({ ...r3.message, parts: r3.message.parts.map((p) => (p === req3 ? { ...p, state: "approval-responded", approval: { id: req3.approval.id, approved: false } } : p)) } as UIMessage, pending3);
assert.ok(denied);
const r4 = await drain((await handleChatStream({ mastra, agentId: "github", version: "v7", params: { messages: [denied], memory: memoryIds } })) as never, r3.message);
assert.deepEqual(executed, [], "denied write tool never ran");
assert.ok(r4.message.parts.some((p) => isToolUIPart(p) && p.state === "output-denied"), "part ends output-denied");
console.log("deny: write tool not executed, part output-denied");
console.log("ALL CHECKS PASSED");
process.exit(0);

